"""Sharing equally: counters dealt one at a time into groups, round and round, as cards
are dealt. A Timer deals the next counter; what can't go round once more is the
remainder. The picture is drawn in its Paint event from the counters dealt so far."""

from vp6 import *

COLORS = (RGB(230, 90, 70), RGB(60, 140, 220), RGB(60, 170, 90), RGB(240, 170, 40),
          RGB(150, 90, 200), RGB(40, 170, 170), RGB(220, 100, 170), RGB(130, 130, 60),
          RGB(100, 110, 230), RGB(200, 120, 60))


class Form1(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Sharing Equally'
        self.Width = 680
        self.Height = 500
        self.lblTotal = Label(self, Caption='Counters: 23', Left=16, Top=14, Width=110, Height=24,
                              TabIndex=1)
        self.sldTotal = Slider(self, Left=126, Top=8, Width=220, Height=36, Min=1, Max=60,
                               Value=23, TickFrequency=5, TabIndex=2)
        self.lblGroups = Label(self, Caption='Groups: 4', Left=366, Top=14, Width=90, Height=24,
                               TabIndex=3)
        self.sldGroups = Slider(self, Left=456, Top=8, Width=200, Height=36, Min=1, Value=4,
                                TabIndex=4)
        self.cmdDeal = CommandButton(self, Caption='&Deal', Left=16, Top=52, Width=100, Height=32,
                                     Default=True, TabIndex=5)
        self.cmdAll = CommandButton(self, Caption='&All at once', Left=126, Top=52, Width=120,
                                    Height=32, TabIndex=6)
        self.picGroups = PictureBox(self, Left=16, Top=96, Width=640, Height=300,
                                    BackColor=0xFAFFFF, TabIndex=7)
        self.lblResult = Label(self, Caption='', Left=16, Top=408, Width=640, Height=60,
                               WordWrap=True, FontSize=16, TabIndex=8)
        self.tmrDeal = Timer(self, Interval=120, Enabled=False)
    # endregion

    dealt = 0  # (the counters dealt so far)

    def Form_Load(self):
        self.restart()

    def sldTotal_Change(self):
        self.restart()

    def sldGroups_Change(self):
        self.restart()

    def restart(self):
        self.tmrDeal.Enabled = False
        self.dealt = 0
        self.lblTotal.Caption = f"Counters: {self.sldTotal.Value}"
        self.lblGroups.Caption = f"Groups: {self.sldGroups.Value}"
        self.show()

    def cmdDeal_Click(self):
        if self.dealt >= self.sldTotal.Value:
            self.dealt = 0
        self.tmrDeal.Enabled = True

    def cmdAll_Click(self):
        self.tmrDeal.Enabled = False
        self.dealt = self.sldTotal.Value
        self.show()

    def tmrDeal_Timer(self):
        """The next counter, to the next group (or, when a round can't be finished,
        to the remainder)."""
        self.dealt += 1
        if self.dealt >= self.sldTotal.Value:
            self.tmrDeal.Enabled = False
        self.show()

    def place(self, counter):
        """Where counter number ``counter`` (from 0) goes: (group, its place in the group),
        or (None, place) in the remainder."""
        total, groups = self.sldTotal.Value, self.sldGroups.Value
        full_rounds = total // groups
        if counter < full_rounds * groups:
            return counter % groups, counter // groups
        return None, counter - full_rounds * groups

    def show(self):
        total, groups = self.sldTotal.Value, self.sldGroups.Value
        quotient, remainder = divmod(total, groups)
        if self.dealt < total:
            each = min(self.dealt // groups, quotient)
            self.lblResult.Caption = f"Dealt {self.dealt} of {total}: {each} in each group so far"
        else:
            self.lblResult.Caption = f"{total} ÷ {groups} = {quotient}" + \
                (f" R {remainder}: {remainder} can't go round again." if remainder else
                 ": no remainder.")
        self.picGroups.Refresh()

    def picGroups_Paint(self):
        pic = self.picGroups
        groups = self.sldGroups.Value
        quotient, remainder = divmod(self.sldTotal.Value, groups)
        columns = min(groups, 5)
        box_w = (pic.ScaleWidth - 24) // columns
        rows = -(-groups // columns)
        box_h = (pic.ScaleHeight - 70) // rows
        ink = RGB(90, 90, 90)
        pic.ForeColor = ink
        pic.FontSize = 9
        for g in range(groups):
            x, y = 12 + g % columns * box_w, 8 + g // columns * box_h
            pic.Line(x + 2, y + 2, x + box_w - 6, y + box_h - 6, ink, "B")
            pic.DrawText(f"Group {g + 1}", x + 2, y + 2, x + box_w - 6, y + 18)
        pic.DrawText("Left over:", 12, pic.ScaleHeight - 56, 100, pic.ScaleHeight - 36,
                     vpLeftJustify)
        pic.FillStyle = vpFSSolid
        for counter in range(self.dealt):
            group, at = self.place(counter)
            if group is None:
                x, y = 22 + at * 22, pic.ScaleHeight - 22
                color = RGB(128, 128, 128)
            else:
                per_row = max(1, (box_w - 20) // 20)
                x = 12 + group % columns * box_w + 16 + at % per_row * 20
                y = 8 + group // columns * box_h + 30 + at // per_row * 20
                color = COLORS[group % len(COLORS)]
            pic.FillColor = color
            pic.Circle(x, y, 8, color)
        pic.FillStyle = vpFSTransparent


if __name__ == "__main__":
    run(Form1)
